import React, { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import { Building2, MapPin, Globe, Mail, Phone, User, Users, Briefcase, Plus, Edit2, CheckCircle2, Clock, X, ChevronRight } from 'lucide-react';
import { EmployerService } from '../../domain/employerService';

const EmployerProfile = () => {
  const { id } = useParams();
  const [employer, setEmployer] = useState(null);
  const [jobs, setJobs] = useState([]);
  const [applications, setApplications] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showEditModal, setShowEditModal] = useState(false);
  const [showJobModal, setShowJobModal] = useState(false);
  const [formData, setFormData] = useState({});
  const [jobFormData, setJobFormData] = useState({
    title: '',
    location: '',
    jobType: 'Full-time',
    experience: '',
    salary: '',
    description: '',
    requirements: '',
    skills: '',
    applicationDeadline: '',
    eligibilityCriteria: {
      minCGPA: 7.0,
      departments: [],
      year: 4
    }
  });
  const [message, setMessage] = useState('');
  const [formLoading, setFormLoading] = useState(false);

  useEffect(() => {
    loadEmployerProfile();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id]);

  const loadEmployerProfile = async () => {
    try {
      setLoading(true);
      const [employerData, jobsData, applicationsData] = await Promise.all([
        EmployerService.getEmployerById(id),
        EmployerService.getEmployerJobs(id),
        EmployerService.getEmployerApplications(id)
      ]);

      setEmployer(employerData);
      setJobs(jobsData);
      setApplications(applicationsData);
      setFormData(employerData || {});
    } catch (error) {
      console.error('Failed to load employer profile:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleEditProfile = () => {
    setFormData(employer);
    setMessage('');
    setShowEditModal(true);
  };

  const handleAddJob = () => {
    setJobFormData({
      title: '',
      location: '',
      jobType: 'Full-time',
      experience: '',
      salary: '',
      description: '',
      requirements: '',
      skills: '',
      applicationDeadline: '',
      eligibilityCriteria: {
        minCGPA: 7.0,
        departments: [],
        year: 4
      }
    });
    setMessage('');
    setShowJobModal(true);
  };

  const handleInputChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleJobInputChange = (e) => {
    if (e.target.name.startsWith('eligibility.')) {
      const field = e.target.name.split('.')[1];
      setJobFormData({
        ...jobFormData,
        eligibilityCriteria: {
          ...jobFormData.eligibilityCriteria,
          [field]: e.target.type === 'number' ? parseFloat(e.target.value) : e.target.value
        }
      });
    } else {
      setJobFormData({
        ...jobFormData,
        [e.target.name]: e.target.value
      });
    }
  };

  const handleDepartmentChange = (e) => {
    const value = e.target.value;
    const departments = jobFormData.eligibilityCriteria.departments;

    if (e.target.checked) {
      setJobFormData({
        ...jobFormData,
        eligibilityCriteria: {
          ...jobFormData.eligibilityCriteria,
          departments: [...departments, value]
        }
      });
    } else {
      setJobFormData({
        ...jobFormData,
        eligibilityCriteria: {
          ...jobFormData.eligibilityCriteria,
          departments: departments.filter(dept => dept !== value)
        }
      });
    }
  };

  const handleProfileSubmit = async (e) => {
    e.preventDefault();
    setFormLoading(true);
    setMessage('');

    try {
      await EmployerService.updateEmployerProfile(id, formData);
      setMessage('Profile updated successfully!');

      setTimeout(() => {
        setShowEditModal(false);
        loadEmployerProfile();
      }, 2000);
    } catch (error) {
      setMessage(error.message);
    } finally {
      setFormLoading(false);
    }
  };

  const handleJobSubmit = async (e) => {
    e.preventDefault();
    setFormLoading(true);
    setMessage('');

    try {
      const jobData = {
        ...jobFormData,
        requirements: jobFormData.requirements.split('\n').filter(req => req.trim()),
        skills: jobFormData.skills.split(',').map(skill => skill.trim()).filter(skill => skill)
      };

      await EmployerService.postJob(id, jobData);
      setMessage('Job posted successfully!');

      setTimeout(() => {
        setShowJobModal(false);
        loadEmployerProfile();
      }, 2000);
    } catch (error) {
      setMessage(error.message);
    } finally {
      setFormLoading(false);
    }
  };

  const getStatusBadge = (status) => {
    const statusConfig = {
      'under_review': { bg: 'bg-yellow-100 text-yellow-800', text: 'Under Review' },
      'shortlisted': { bg: 'bg-blue-100 text-blue-800', text: 'Shortlisted' },
      'accepted': { bg: 'bg-green-100 text-green-800', text: 'Accepted' },
      'rejected': { bg: 'bg-red-100 text-red-800', text: 'Rejected' },
      'active': { bg: 'bg-green-100 text-green-800', text: 'Active' },
      'inactive': { bg: 'bg-gray-100 text-gray-800', text: 'Inactive' }
    };

    const config = statusConfig[status] || { bg: 'bg-gray-100 text-gray-800', text: status };
    return <span className={`px-2.5 py-1 rounded-full text-xs font-semibold ${config.bg}`}>{config.text}</span>;
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="w-12 h-12 border-4 border-primary-200 border-t-primary-600 rounded-full animate-spin"></div>
      </div>
    );
  }

  if (!employer) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center p-6">
        <div className="bg-red-50 text-red-600 px-6 py-4 rounded-xl border border-red-100 font-medium">
          Employer not found.
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#F9FAFB] pb-24 font-sans text-gray-900">
      {/* Header Area with Gradient */}
      <div className="h-64 bg-gradient-to-r from-primary-900 via-primary-800 to-secondary-900 relative">
        <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')] opacity-10"></div>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 -mt-32 relative z-10">

        {/* Top Profile Card */}
        <div className="bg-white rounded-3xl shadow-soft p-6 md:p-10 mb-8 border border-gray-100 flex flex-col md:flex-row gap-8 items-start">
          <div className="w-32 h-32 md:w-40 md:h-40 rounded-2xl bg-white p-2 shadow-lg shrink-0 border border-gray-100 overflow-hidden relative group">
            <img 
              src={employer.logo || 'https://via.placeholder.com/200x200?text=Company'} 
              alt="Company Logo" 
              className="w-full h-full object-contain rounded-xl"
            />
          </div>

          <div className="flex-1 w-full">
            <div className="flex flex-col md:flex-row md:justify-between md:items-start gap-4 mb-4">
              <div>
                <div className="flex items-center gap-3 mb-2">
                  <h1 className="text-3xl md:text-4xl font-extrabold text-gray-900 tracking-tight">{employer.companyName}</h1>
                  {employer.isVerified ? (
                    <div className="flex items-center gap-1 bg-green-50 text-green-700 px-2.5 py-1 rounded-full text-sm font-semibold border border-green-200">
                      <CheckCircle2 size={16} /> Verified
                    </div>
                  ) : (
                    <div className="flex items-center gap-1 bg-yellow-50 text-yellow-700 px-2.5 py-1 rounded-full text-sm font-semibold border border-yellow-200">
                      <Clock size={16} /> Pending
                    </div>
                  )}
                </div>
                <p className="text-lg text-gray-500 font-medium mb-4 flex items-center gap-2">
                  <Building2 size={20} className="text-primary-500"/> {employer.industry}
                </p>

                <div className="flex flex-wrap gap-3">
                  <span className="px-3 py-1.5 bg-gray-100 text-gray-700 rounded-lg text-sm font-medium border border-gray-200 flex items-center gap-2">
                    <Users size={16} className="text-gray-400"/> {employer.companySize || '50-200'} Employees
                  </span>
                  <span className="px-3 py-1.5 bg-primary-50 text-primary-700 rounded-lg text-sm font-medium border border-primary-100 flex items-center gap-2">
                    <Briefcase size={16} className="text-primary-400"/> {jobs.length} Active Jobs
                  </span>
                </div>
              </div>

              <div className="flex gap-3 w-full md:w-auto mt-4 md:mt-0 shrink-0">
                <button onClick={handleEditProfile} className="flex-1 md:flex-none flex items-center justify-center gap-2 px-6 py-2.5 bg-white border border-gray-200 text-gray-700 font-semibold rounded-xl hover:bg-gray-50 transition-colors shadow-sm">
                  <Edit2 size={18} /> Edit Profile
                </button>
                {employer.isVerified && (
                  <button onClick={handleAddJob} className="flex-1 md:flex-none flex items-center justify-center gap-2 px-6 py-2.5 bg-primary-600 text-white font-semibold rounded-xl hover:bg-primary-700 transition-colors shadow-md hover:shadow-lg">
                    <Plus size={18} /> Post Job
                  </button>
                )}
              </div>
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

          {/* Left Column (Sidebar-ish) */}
          <div className="space-y-8">

            {/* About Company */}
            <div className="bg-white rounded-3xl shadow-sm border border-gray-100 p-6 md:p-8">
              <h3 className="text-xl font-bold text-gray-900 mb-4">About</h3>
              <p className="text-gray-600 leading-relaxed">
                {employer.description || 'This company hasn\'t provided a description yet. They are probably busy building awesome things!'}
              </p>
            </div>

            {/* Contact Information */}
            <div className="bg-white rounded-3xl shadow-sm border border-gray-100 p-6 md:p-8">
              <h3 className="text-xl font-bold text-gray-900 mb-6">Contact & Details</h3>
              <ul className="space-y-5">
                <li className="flex items-start gap-4">
                  <div className="w-10 h-10 rounded-xl bg-primary-50 text-primary-600 flex items-center justify-center shrink-0">
                    <Globe size={20} />
                  </div>
                  <div>
                    <p className="text-sm font-medium text-gray-500 mb-0.5">Website</p>
                    <a href={employer.website} target="_blank" rel="noopener noreferrer" className="text-gray-900 font-semibold hover:text-primary-600 transition-colors break-all">
                      {employer.website || 'Not provided'}
                    </a>
                  </div>
                </li>
                <li className="flex items-start gap-4">
                  <div className="w-10 h-10 rounded-xl bg-primary-50 text-primary-600 flex items-center justify-center shrink-0">
                    <Mail size={20} />
                  </div>
                  <div>
                    <p className="text-sm font-medium text-gray-500 mb-0.5">Email</p>
                    <a href={`mailto:${employer.email}`} className="text-gray-900 font-semibold hover:text-primary-600 transition-colors break-all">
                      {employer.email}
                    </a>
                  </div>
                </li>
                <li className="flex items-start gap-4">
                  <div className="w-10 h-10 rounded-xl bg-primary-50 text-primary-600 flex items-center justify-center shrink-0">
                    <Phone size={20} />
                  </div>
                  <div>
                    <p className="text-sm font-medium text-gray-500 mb-0.5">Phone</p>
                    <a href={`tel:${employer.phone}`} className="text-gray-900 font-semibold hover:text-primary-600 transition-colors">
                      {employer.phone || 'Not provided'}
                    </a>
                  </div>
                </li>
                <li className="flex items-start gap-4">
                  <div className="w-10 h-10 rounded-xl bg-primary-50 text-primary-600 flex items-center justify-center shrink-0">
                    <MapPin size={20} />
                  </div>
                  <div>
                    <p className="text-sm font-medium text-gray-500 mb-0.5">Location</p>
                    <p className="text-gray-900 font-semibold">
                      {employer.address || 'Not provided'}
                    </p>
                  </div>
                </li>
              </ul>
            </div>

            {/* Key Contact */}
            <div className="bg-white rounded-3xl shadow-sm border border-gray-100 p-6 md:p-8 bg-gradient-to-br from-gray-50 to-white">
              <h3 className="text-xl font-bold text-gray-900 mb-6">Key Contact</h3>
              <div className="flex items-center gap-4">
                <div className="w-14 h-14 rounded-full bg-secondary-100 text-secondary-600 flex items-center justify-center shrink-0 text-xl font-bold">
                  {(employer.contactPerson || 'A').charAt(0).toUpperCase()}
                </div>
                <div>
                  <p className="text-lg font-bold text-gray-900">{employer.contactPerson || 'Admin'}</p>
                  <p className="text-gray-500 font-medium">{employer.contactDesignation || 'Recruitment'}</p>
                </div>
              </div>
            </div>

          </div>

          {/* Right Column (Main Content) */}
          <div className="lg:col-span-2 space-y-8">

            {/* Jobs Posted */}
            <div className="bg-white rounded-3xl shadow-sm border border-gray-100 overflow-hidden">
              <div className="p-6 md:p-8 border-b border-gray-100 flex justify-between items-center bg-gray-50/50">
                <div>
                  <h3 className="text-xl font-bold text-gray-900">Active Job Postings</h3>
                  <p className="text-sm text-gray-500 mt-1">Manage and track your open roles.</p>
                </div>
                <span className="bg-primary-100 text-primary-800 font-bold px-3 py-1 rounded-full text-sm">
                  {jobs.length}
                </span>
              </div>

              <div className="p-0">
                {jobs.length > 0 ? (
                  <div className="divide-y divide-gray-100">
                    {jobs.map(job => (
                      <div key={job.id} className="p-6 md:p-8 hover:bg-gray-50 transition-colors group flex flex-col md:flex-row md:items-center justify-between gap-6">
                        <div className="flex-1">
                          <Link to={`/job/${job.id}`} className="text-lg font-bold text-gray-900 hover:text-primary-600 transition-colors mb-2 inline-block">
                            {job.title}
                          </Link>
                          <div className="flex flex-wrap items-center gap-3 text-sm text-gray-500 font-medium mb-4">
                            <span className="flex items-center gap-1.5"><MapPin size={16}/> {job.location}</span>
                            <span className="w-1 h-1 bg-gray-300 rounded-full"></span>
                            <span className="flex items-center gap-1.5"><Briefcase size={16}/> {job.jobType}</span>
                            <span className="w-1 h-1 bg-gray-300 rounded-full"></span>
                            <span>{new Date(job.postedDate).toLocaleDateString()}</span>
                          </div>
                          <div className="flex items-center gap-4">
                            {getStatusBadge(job.status)}
                            <span className="text-sm font-semibold text-gray-600 flex items-center gap-1.5">
                              <Users size={16} className="text-gray-400"/> {job.applicationsReceived} Applications
                            </span>
                          </div>
                        </div>
                        <Link to={`/job/${job.id}`} className="shrink-0 w-12 h-12 rounded-full bg-white border border-gray-200 flex items-center justify-center text-gray-400 group-hover:bg-primary-50 group-hover:text-primary-600 group-hover:border-primary-200 transition-all shadow-sm">
                          <ChevronRight size={20} />
                        </Link>
                      </div>
                    ))}
                  </div>
                ) : (
                  <div className="p-12 text-center">
                    <div className="w-16 h-16 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-4 border border-gray-100">
                      <Briefcase className="text-gray-400" size={24} />
                    </div>
                    <h4 className="text-lg font-bold text-gray-900 mb-2">No jobs posted yet</h4>
                    <p className="text-gray-500 mb-6 max-w-sm mx-auto">Start building your team by posting your first job opportunity today.</p>
                    {employer.isVerified && (
                      <button onClick={handleAddJob} className="bg-primary-600 text-white px-6 py-2.5 rounded-xl font-semibold hover:bg-primary-700 transition-colors shadow-md inline-flex items-center gap-2">
                        <Plus size={18} /> Post Your First Job
                      </button>
                    )}
                  </div>
                )}
              </div>
            </div>

            {/* Recent Applications */}
            <div className="bg-white rounded-3xl shadow-sm border border-gray-100 overflow-hidden">
              <div className="p-6 md:p-8 border-b border-gray-100 flex justify-between items-center bg-gray-50/50">
                <div>
                  <h3 className="text-xl font-bold text-gray-900">Recent Applications</h3>
                  <p className="text-sm text-gray-500 mt-1">Candidates who recently applied.</p>
                </div>
              </div>

              <div className="p-0">
                {applications.length > 0 ? (
                  <div className="overflow-x-auto">
                    <table className="w-full text-left border-collapse">
                      <thead>
                        <tr className="bg-gray-50/50 border-b border-gray-100">
                          <th className="py-4 px-6 md:px-8 text-sm font-semibold text-gray-500 uppercase tracking-wider">Candidate</th>
                          <th className="py-4 px-6 md:px-8 text-sm font-semibold text-gray-500 uppercase tracking-wider">Role</th>
                          <th className="py-4 px-6 md:px-8 text-sm font-semibold text-gray-500 uppercase tracking-wider">Date</th>
                          <th className="py-4 px-6 md:px-8 text-sm font-semibold text-gray-500 uppercase tracking-wider">Status</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-gray-100">
                        {applications.slice(0, 10).map(application => (
                          <tr key={application.id} className="hover:bg-gray-50/80 transition-colors">
                            <td className="py-4 px-6 md:px-8">
                              <div className="flex items-center gap-3">
                                <div className="w-8 h-8 rounded-full bg-primary-100 text-primary-700 flex items-center justify-center font-bold text-xs shrink-0">
                                  {application.studentName.charAt(0).toUpperCase()}
                                </div>
                                <span className="font-bold text-gray-900">{application.studentName}</span>
                              </div>
                            </td>
                            <td className="py-4 px-6 md:px-8 font-medium text-gray-700">{application.jobTitle}</td>
                            <td className="py-4 px-6 md:px-8 text-gray-500 text-sm">{new Date(application.applicationDate).toLocaleDateString()}</td>
                            <td className="py-4 px-6 md:px-8">{getStatusBadge(application.status)}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                ) : (
                  <div className="p-12 text-center">
                    <div className="w-16 h-16 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-4 border border-gray-100">
                      <User className="text-gray-400" size={24} />
                    </div>
                    <p className="text-gray-500 font-medium">No applications received yet.</p>
                  </div>
                )}
              </div>
            </div>

          </div>
        </div>
      </div>

      {/* Tailwind Modals (replacing React-Bootstrap Modals) */}

      {/* Edit Profile Modal */}
      {showEditModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 sm:p-6 bg-gray-900/60 backdrop-blur-sm overflow-y-auto">
          <div className="bg-white rounded-3xl w-full max-w-3xl shadow-2xl overflow-hidden my-auto animate-fade-in-up">
            <div className="px-6 py-5 border-b border-gray-100 flex justify-between items-center bg-gray-50/50 sticky top-0 z-10">
              <h3 className="text-xl font-bold text-gray-900">Edit Company Profile</h3>
              <button onClick={() => setShowEditModal(false)} className="text-gray-400 hover:text-gray-700 bg-white hover:bg-gray-100 p-2 rounded-full transition-colors border border-transparent hover:border-gray-200">
                <X size={20} />
              </button>
            </div>

            <div className="p-6 md:p-8 max-h-[70vh] overflow-y-auto">
              {message && (
                <div className={`p-4 rounded-xl mb-6 font-medium flex items-start gap-3 ${message.includes('successfully') ? 'bg-green-50 text-green-800 border border-green-200' : 'bg-red-50 text-red-800 border border-red-200'}`}>
                  {message.includes('successfully') ? <CheckCircle2 size={20} className="shrink-0 mt-0.5" /> : <X size={20} className="shrink-0 mt-0.5" />}
                  <p>{message}</p>
                </div>
              )}

              <form onSubmit={handleProfileSubmit} className="space-y-6">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <label className="block text-sm font-bold text-gray-700 mb-2">Company Name <span className="text-red-500">*</span></label>
                    <input type="text" name="companyName" value={formData.companyName || ''} onChange={handleInputChange} required className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:border-primary-500 focus:ring-2 focus:ring-primary-200 outline-none transition-all font-medium text-gray-900 bg-gray-50/50 focus:bg-white" />
                  </div>
                  <div>
                    <label className="block text-sm font-bold text-gray-700 mb-2">Industry <span className="text-red-500">*</span></label>
                    <input type="text" name="industry" value={formData.industry || ''} onChange={handleInputChange} required className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:border-primary-500 focus:ring-2 focus:ring-primary-200 outline-none transition-all font-medium text-gray-900 bg-gray-50/50 focus:bg-white" />
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <label className="block text-sm font-bold text-gray-700 mb-2">Email <span className="text-red-500">*</span></label>
                    <input type="email" name="email" value={formData.email || ''} onChange={handleInputChange} required className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:border-primary-500 focus:ring-2 focus:ring-primary-200 outline-none transition-all font-medium text-gray-900 bg-gray-50/50 focus:bg-white" />
                  </div>
                  <div>
                    <label className="block text-sm font-bold text-gray-700 mb-2">Phone <span className="text-red-500">*</span></label>
                    <input type="tel" name="phone" value={formData.phone || ''} onChange={handleInputChange} required className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:border-primary-500 focus:ring-2 focus:ring-primary-200 outline-none transition-all font-medium text-gray-900 bg-gray-50/50 focus:bg-white" />
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-bold text-gray-700 mb-2">Website <span className="text-red-500">*</span></label>
                  <input type="url" name="website" value={formData.website || ''} onChange={handleInputChange} required className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:border-primary-500 focus:ring-2 focus:ring-primary-200 outline-none transition-all font-medium text-gray-900 bg-gray-50/50 focus:bg-white" />
                </div>

                <div>
                  <label className="block text-sm font-bold text-gray-700 mb-2">Address <span className="text-red-500">*</span></label>
                  <input type="text" name="address" value={formData.address || ''} onChange={handleInputChange} required className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:border-primary-500 focus:ring-2 focus:ring-primary-200 outline-none transition-all font-medium text-gray-900 bg-gray-50/50 focus:bg-white" />
                </div>

                <div>
                  <label className="block text-sm font-bold text-gray-700 mb-2">Company Description</label>
                  <textarea rows={4} name="description" value={formData.description || ''} onChange={handleInputChange} className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:border-primary-500 focus:ring-2 focus:ring-primary-200 outline-none transition-all font-medium text-gray-900 bg-gray-50/50 focus:bg-white resize-none" />
                </div>

                <div className="pt-4 border-t border-gray-100 flex gap-3 justify-end sticky bottom-0 bg-white">
                  <button type="button" onClick={() => setShowEditModal(false)} disabled={formLoading} className="px-6 py-2.5 rounded-xl font-bold text-gray-700 bg-white border border-gray-200 hover:bg-gray-50 transition-colors">
                    Cancel
                  </button>
                  <button type="submit" disabled={formLoading} className="px-6 py-2.5 rounded-xl font-bold text-white bg-primary-600 hover:bg-primary-700 transition-colors shadow-md flex items-center gap-2">
                    {formLoading ? (
                       <><div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div> Updating...</>
                    ) : 'Update Profile'}
                  </button>
                </div>
              </form>
            </div>
          </div>
        </div>
      )}

      {/* Add Job Modal */}
      {showJobModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 sm:p-6 bg-gray-900/60 backdrop-blur-sm overflow-y-auto">
          <div className="bg-white rounded-3xl w-full max-w-4xl shadow-2xl overflow-hidden my-auto animate-fade-in-up">
            <div className="px-6 py-5 border-b border-gray-100 flex justify-between items-center bg-gray-50/50 sticky top-0 z-10">
              <h3 className="text-xl font-bold text-gray-900">Post New Job</h3>
              <button onClick={() => setShowJobModal(false)} className="text-gray-400 hover:text-gray-700 bg-white hover:bg-gray-100 p-2 rounded-full transition-colors border border-transparent hover:border-gray-200">
                <X size={20} />
              </button>
            </div>

            <div className="p-6 md:p-8 max-h-[75vh] overflow-y-auto">
              {message && (
                <div className={`p-4 rounded-xl mb-6 font-medium flex items-start gap-3 ${message.includes('successfully') ? 'bg-green-50 text-green-800 border border-green-200' : 'bg-red-50 text-red-800 border border-red-200'}`}>
                  {message.includes('successfully') ? <CheckCircle2 size={20} className="shrink-0 mt-0.5" /> : <X size={20} className="shrink-0 mt-0.5" />}
                  <p>{message}</p>
                </div>
              )}

              <form onSubmit={handleJobSubmit} className="space-y-8">

                {/* Basic Info Section */}
                <div>
                  <h4 className="text-lg font-bold text-gray-900 mb-4 pb-2 border-b border-gray-100">Basic Information</h4>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
                    <div>
                      <label className="block text-sm font-bold text-gray-700 mb-2">Job Title <span className="text-red-500">*</span></label>
                      <input type="text" name="title" value={jobFormData.title} onChange={handleJobInputChange} required className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:border-primary-500 focus:ring-2 focus:ring-primary-200 outline-none transition-all font-medium text-gray-900 bg-gray-50/50 focus:bg-white" />
                    </div>
                    <div>
                      <label className="block text-sm font-bold text-gray-700 mb-2">Location <span className="text-red-500">*</span></label>
                      <input type="text" name="location" value={jobFormData.location} onChange={handleJobInputChange} required className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:border-primary-500 focus:ring-2 focus:ring-primary-200 outline-none transition-all font-medium text-gray-900 bg-gray-50/50 focus:bg-white" />
                    </div>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
                    <div>
                      <label className="block text-sm font-bold text-gray-700 mb-2">Job Type <span className="text-red-500">*</span></label>
                      <select name="jobType" value={jobFormData.jobType} onChange={handleJobInputChange} required className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:border-primary-500 focus:ring-2 focus:ring-primary-200 outline-none transition-all font-medium text-gray-900 bg-gray-50/50 focus:bg-white appearance-none">
                        <option value="Full-time">Full-time</option>
                        <option value="Part-time">Part-time</option>
                        <option value="Internship">Internship</option>
                        <option value="Contract">Contract</option>
                      </select>
                    </div>
                    <div>
                      <label className="block text-sm font-bold text-gray-700 mb-2">Experience <span className="text-red-500">*</span></label>
                      <input type="text" name="experience" value={jobFormData.experience} onChange={handleJobInputChange} placeholder="e.g., 0-2 years" required className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:border-primary-500 focus:ring-2 focus:ring-primary-200 outline-none transition-all font-medium text-gray-900 bg-gray-50/50 focus:bg-white" />
                    </div>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div>
                      <label className="block text-sm font-bold text-gray-700 mb-2">Salary <span className="text-red-500">*</span></label>
                      <input type="text" name="salary" value={jobFormData.salary} onChange={handleJobInputChange} placeholder="e.g., $70,000 - $90,000" required className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:border-primary-500 focus:ring-2 focus:ring-primary-200 outline-none transition-all font-medium text-gray-900 bg-gray-50/50 focus:bg-white" />
                    </div>
                    <div>
                      <label className="block text-sm font-bold text-gray-700 mb-2">Application Deadline <span className="text-red-500">*</span></label>
                      <input type="date" name="applicationDeadline" value={jobFormData.applicationDeadline} onChange={handleJobInputChange} required className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:border-primary-500 focus:ring-2 focus:ring-primary-200 outline-none transition-all font-medium text-gray-900 bg-gray-50/50 focus:bg-white" />
                    </div>
                  </div>
                </div>

                {/* Details Section */}
                <div>
                  <h4 className="text-lg font-bold text-gray-900 mb-4 pb-2 border-b border-gray-100">Job Details</h4>

                  <div className="mb-6">
                    <label className="block text-sm font-bold text-gray-700 mb-2">Job Description <span className="text-red-500">*</span></label>
                    <textarea rows={4} name="description" value={jobFormData.description} onChange={handleJobInputChange} required className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:border-primary-500 focus:ring-2 focus:ring-primary-200 outline-none transition-all font-medium text-gray-900 bg-gray-50/50 focus:bg-white resize-none" />
                  </div>

                  <div className="mb-6">
                    <label className="block text-sm font-bold text-gray-700 mb-2">Requirements (one per line) <span className="text-red-500">*</span></label>
                    <textarea rows={4} name="requirements" value={jobFormData.requirements} onChange={handleJobInputChange} placeholder="Bachelor's degree in Computer Science&#10;Proficiency in JavaScript&#10;Experience with React" required className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:border-primary-500 focus:ring-2 focus:ring-primary-200 outline-none transition-all font-medium text-gray-900 bg-gray-50/50 focus:bg-white resize-none" />
                  </div>

                  <div>
                    <label className="block text-sm font-bold text-gray-700 mb-2">Skills (comma separated)</label>
                    <input type="text" name="skills" value={jobFormData.skills} onChange={handleJobInputChange} placeholder="JavaScript, React, Node.js, Python" className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:border-primary-500 focus:ring-2 focus:ring-primary-200 outline-none transition-all font-medium text-gray-900 bg-gray-50/50 focus:bg-white" />
                  </div>
                </div>

                {/* Eligibility Section */}
                <div className="bg-gray-50 p-6 rounded-2xl border border-gray-100">
                  <h4 className="text-lg font-bold text-gray-900 mb-4">Eligibility Criteria</h4>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
                    <div>
                      <label className="block text-sm font-bold text-gray-700 mb-2">Minimum CGPA</label>
                      <input type="number" step="0.1" min="0" max="10" name="eligibility.minCGPA" value={jobFormData.eligibilityCriteria.minCGPA} onChange={handleJobInputChange} className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:border-primary-500 focus:ring-2 focus:ring-primary-200 outline-none transition-all font-medium text-gray-900 bg-white focus:bg-white" />
                    </div>
                    <div>
                      <label className="block text-sm font-bold text-gray-700 mb-2">Minimum Year</label>
                      <select name="eligibility.year" value={jobFormData.eligibilityCriteria.year} onChange={handleJobInputChange} className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:border-primary-500 focus:ring-2 focus:ring-primary-200 outline-none transition-all font-medium text-gray-900 bg-white focus:bg-white appearance-none">
                        <option value={1}>1st Year</option>
                        <option value={2}>2nd Year</option>
                        <option value={3}>3rd Year</option>
                        <option value={4}>4th Year</option>
                      </select>
                    </div>
                  </div>

                  <div>
                    <label className="block text-sm font-bold text-gray-700 mb-3">Eligible Departments</label>
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
                      {['Computer Science', 'Information Technology', 'Electronics', 'Mechanical', 'Civil', 'Electrical'].map(dept => (
                        <label key={dept} className="flex items-center gap-3 p-3 bg-white border border-gray-200 rounded-xl cursor-pointer hover:border-primary-300 transition-colors">
                          <input type="checkbox" value={dept} checked={jobFormData.eligibilityCriteria.departments.includes(dept)} onChange={handleDepartmentChange} className="w-5 h-5 text-primary-600 border-gray-300 rounded focus:ring-primary-500 accent-primary-600" />
                          <span className="text-sm font-medium text-gray-700">{dept}</span>
                        </label>
                      ))}
                    </div>
                  </div>
                </div>

                <div className="pt-6 border-t border-gray-100 flex gap-3 justify-end sticky bottom-0 bg-white">
                  <button type="button" onClick={() => setShowJobModal(false)} disabled={formLoading} className="px-6 py-2.5 rounded-xl font-bold text-gray-700 bg-white border border-gray-200 hover:bg-gray-50 transition-colors">
                    Cancel
                  </button>
                  <button type="submit" disabled={formLoading} className="px-6 py-2.5 rounded-xl font-bold text-white bg-primary-600 hover:bg-primary-700 transition-colors shadow-md flex items-center gap-2">
                    {formLoading ? (
                      <><div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div> Posting...</>
                    ) : 'Post Job'}
                  </button>
                </div>
              </form>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default EmployerProfile;
